import{_ as p,a0 as r,w as a,s as u,ao as o,I as l,x as i,a1 as s,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"Linux 開發的五大必備工具 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 開發的五大必備工具 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 開發的五大必備工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 開發的五大必備工具 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180803 5 Essential Tools for Linux Development","title":"Linux 開發的五大必備工具","tag":"201810","desc":""},"relativePath":"201810/20180803 5 Essential Tools for Linux Development.md","filePath":"[post].md"}'),d={name:"201810/20180803 5 Essential Tools for Linux Development.md"};function m(f,t,g,k,b,x){const e=r("Link");return a(),u("div",null,[t[39]||(t[39]=o('<h1 id="linux-開發的五大必備工具" tabindex="-1">Linux 開發的五大必備工具 <a class="header-anchor" href="#linux-開發的五大必備工具" aria-label="Permalink to “Linux 開發的五大必備工具”">​</a></h1><blockquote><p>Linux 上的開發工具如此之多，以至於會擔心找不到恰好適合你的。</p></blockquote><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/dev-tools.png?itok=kkDNylRg" alt=""></p><p>Linux 已經成為工作、娛樂和個人生活等多個領域的支柱，人們已經越來越離不開它。在 Linux 的幫助下，技術的變革速度超出了人們的想像，Linux 開發的速度也以指數規模增長。因此，越來越多的開發者也不斷地加入開源和學習 Linux 開發地潮流當中。在這個過程之中，合適的工具是必不可少的，可喜的是，隨着 Linux 的發展，大量適用於 Linux 的開發工具也不斷成熟。甚至可以説，這樣的工具已經多得有點驚人。</p><p>為了選擇更合適自己的開發工具，縮小選擇範圍是很必要的。但是這篇文章並不會要求你必須使用某個工具，而只是縮小到五個工具類別，然後對每個類別提供一個例子。然而，對於大多數類別，都會有不止一種選擇。下面我們來看一下。</p><h3 id="容器" tabindex="-1">容器 <a class="header-anchor" href="#容器" aria-label="Permalink to “容器”">​</a></h3><p>放眼於現實，現在已經是容器的時代了。容器既及其容易部署，又可以方便地構建開發環境。如果你針對的是特定的平台的開發，將開發流程所需要的各種工具都創建到容器映像中是一種很好的方法，只要使用這一個容器映像，就能夠快速啓動大量運行所需服務的實例。</p>',7)),l("p",null,[t[1]||(t[1]=i("一個使用容器的最佳範例是使用 ",-1)),s(e,{href:"https://www.docker.com/"},{default:n(()=>[...t[0]||(t[0]=[i("Docker",-1)])]),_:1}),t[2]||(t[2]=i("，使用容器（或 Docker）有這些好處：",-1))]),t[40]||(t[40]=l("ul",null,[l("li",null,"開發環境保持一致"),l("li",null,"部署後即可運行"),l("li",null,"易於跨平台部署"),l("li",null,"Docker 映像適用於多種開發環境和語言"),l("li",null,"部署單個容器或容器集羣都並不繁瑣")],-1)),l("p",null,[t[4]||(t[4]=i("通過 ",-1)),s(e,{href:"https://hub.docker.com/"},{default:n(()=>[...t[3]||(t[3]=[i("Docker Hub",-1)])]),_:1}),t[5]||(t[5]=i("，幾乎可以找到適用於任何平台、任何開發環境、任何服務器、任何服務的映像，幾乎可以滿足任何一種需求。使用 Docker Hub 中的映像，就相當於免除了搭建開發環境的步驟，可以直接開始開發應用程序、服務器、API 或服務。",-1))]),t[41]||(t[41]=o('<p>Docker 在所有 Linux 平台上都很容易安裝，例如可以通過終端輸入以下命令在 Ubuntu 上安裝 Docker：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install docker.io</span></span></code></pre></div><p>Docker 安裝完畢後，就可以從 Docker 倉庫中拉取映像，然後開始開發和部署了（如下圖）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/5devtools_1.jpg?itok=V1Bsbkg9" alt="Docker images" title="Docker images"></p><p><em>圖 1： Docker 鏡像準備部署</em></p><h3 id="版本控制工具" tabindex="-1">版本控制工具 <a class="header-anchor" href="#版本控制工具" aria-label="Permalink to “版本控制工具”">​</a></h3>',6)),l("p",null,[t[8]||(t[8]=i("如果你正在開發一個大型項目，又或者參與團隊開發，版本控制工具是必不可少的，它可以用於記錄代碼變更、提交代碼以及合併代碼。如果沒有這樣的工具，項目幾乎無法妥善管理。在 Linux 系統上，",-1)),s(e,{href:"https://git-scm.com/"},{default:n(()=>[...t[6]||(t[6]=[i("Git",-1)])]),_:1}),t[9]||(t[9]=i(" 和 ",-1)),s(e,{href:"https://github.com/"},{default:n(()=>[...t[7]||(t[7]=[i("GitHub",-1)])]),_:1}),t[10]||(t[10]=i(" 的易用性和流行程度是其它版本控制工具無法比擬的。如果你對 Git 和 GitHub 還不太熟悉，可以簡單理解為 Git 是在本地計算機上安裝的版本控制系統，而 GitHub 則是用於上傳和管理項目的遠程存儲庫。 Git 可以安裝在大多數的 Linux 發行版上。例如在基於 Debian 的系統上，只需要通過以下這一條簡單的命令就可以安裝：",-1))]),t[42]||(t[42]=o('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install git</span></span></code></pre></div><p>安裝完畢後，就可以使用 Git 來實施版本控制了（如下圖）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/5devtools_2.jpg?itok=YJjhe4O6" alt="Git installed" title="Git installed"></p><p><em>圖 2：Git 已經安裝，可以用於很多重要任務</em></p>',4)),l("p",null,[t[12]||(t[12]=i("Github 會要求用户創建一個帳户。用户可以免費使用 GitHub 來管理非商用項目，當然也可以使用 GitHub 的付費模式（更多相關信息，可以參閲",-1)),s(e,{href:"https://github.com/pricing"},{default:n(()=>[...t[11]||(t[11]=[i("價格矩陣",-1)])]),_:1}),t[13]||(t[13]=i("）。",-1))]),t[43]||(t[43]=l("h3",{id:"文本編輯器",tabindex:"-1"},[i("文本編輯器 "),l("a",{class:"header-anchor",href:"#文本編輯器","aria-label":"Permalink to “文本編輯器”"},"​")],-1)),t[44]||(t[44]=l("p",null,"如果沒有文本編輯器，在 Linux 上開發將會變得異常艱難。當然，文本編輯器之間孰優孰劣，具體還是要取決於開發者的需求。對於文本編輯器，有人可能會使用 vim、emacs 或 nano，也有人會使用帶有 GUI 的編輯器。但由於重點在於開發，我們需要的是一種能夠滿足開發人員需求的工具。不過我首先要説，vim 對於開發人員來説確實是一個利器，但前提是要對 vim 非常熟悉，在這種前提下，vim 能夠滿足你的所有需求，甚至還能給你更好的體驗。然而，對於一些開發者（尤其是剛開始接觸 Linux 的新手）來説，這不僅難以幫助他們快速達成需求，甚至還會是一個需要逾越的障礙。考慮到這篇文章的目標是幫助 Linux 的新手（而不僅僅是為各種編輯器的死忠粉宣傳他們擁護的編輯器），我更傾向於使用 GUI 編輯器。",-1)),l("p",null,[t[15]||(t[15]=i("就文本編輯器而論，選擇 ",-1)),s(e,{href:"http://bluefish.openoffice.nl/index.html"},{default:n(()=>[...t[14]||(t[14]=[i("Bluefish",-1)])]),_:1}),t[16]||(t[16]=i(" 一般不會有錯。 Bluefish 可以從大部分軟件庫中安裝，它支持項目管理、遠程文件多線程操作、搜索和替換、遞歸打開文件、側邊欄、集成 make/lint/weblint/xmllint、無限制撤銷/重做、在線拼寫檢查、自動恢復、全屏編輯、語法高亮（如下圖）、多種語言等等。",-1))]),t[45]||(t[45]=l("p",null,[l("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/5devtools_3.jpg?itok=66A7Svme",alt:"Bluefish",title:"Bluefish"})],-1)),t[46]||(t[46]=l("p",null,[l("em",null,"圖 3：運行在 Ubuntu 18.04 上的 Bluefish")],-1)),t[47]||(t[47]=l("h3",{id:"ide",tabindex:"-1"},[i("IDE "),l("a",{class:"header-anchor",href:"#ide","aria-label":"Permalink to “IDE”"},"​")],-1)),l("p",null,[t[18]||(t[18]=l("ruby",null,[i("集成開發環境"),l("rt",null,"Integrated Development Environment")],-1)),t[19]||(t[19]=i("（IDE）是包含一整套全面的工具、可以實現一站式功能的開發環境。 開發者除了可以使用 IDE 編寫代碼，還可以編寫文檔和構建軟件。在 Linux 上也有很多適用的 IDE，其中 ",-1)),s(e,{href:"https://www.geany.org/"},{default:n(()=>[...t[17]||(t[17]=[i("Geany",-1)])]),_:1}),t[20]||(t[20]=i(" 就包含在標準軟件庫中，它對用户非常友好，功能也相當強大。 Geany 具有語法高亮、代碼摺疊、自動完成，構建代碼片段、自動關閉 XML 和 HTML 標籤、調用提示、支持多種文件類型、符號列表、代碼導航、構建編譯，簡單的項目管理和內置的插件系統等強大功能。",-1))]),t[48]||(t[48]=o('<p>Geany 也能在系統上輕鬆安裝，例如執行以下命令在基於 Debian 的 Linux 發行版上安裝 Geany：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install geany</span></span></code></pre></div><p>安裝完畢後，就可以快速上手這個易用且強大的 IDE 了（如下圖）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/5devtools_4.jpg?itok=jRcA-0ue" alt="Geany" title="Geany"></p><p><em>圖 4：Geany 可以作為你的 IDE</em></p><h3 id="文本比較工具" tabindex="-1">文本比較工具 <a class="header-anchor" href="#文本比較工具" aria-label="Permalink to “文本比較工具”">​</a></h3>',6)),l("p",null,[t[22]||(t[22]=i("有時候會需要比較兩個文件的內容來找到它們之間的不同之處，它們可能是同一文件的兩個不同副本（有一個經過編譯，而另一個沒有）。這種情況下，你肯定不想要憑藉肉眼來找出差異，而是想要使用像 ",-1)),s(e,{href:"http://meldmerge.org/"},{default:n(()=>[...t[21]||(t[21]=[i("Meld",-1)])]),_:1}),t[23]||(t[23]=i(" 這樣的工具。 Meld 是針對開發者的文本比較和合並工具，可以使用 Meld 來發現兩個文件之間的差異。雖然你可以使用命令列中的文本比較工具，但就效率而論，Meld 無疑更為優秀。",-1))]),t[49]||(t[49]=o('<p>Meld 可以打開兩個文件進行比較，並突出顯示文件之間的差異之處。 Meld 還允許用户從兩個文件的其中一方合併差異（下圖顯示了 Meld 同時打開兩個文件）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/5devtools_5.jpg?itok=eLkfM9oZ" alt="Comparing two files" title="Comparing two files"></p><p><em>圖 5： 以簡單差異的模式比較兩個文件</em></p><p>Meld 也可以通過大多數標準的軟件庫安裝，在基於 Debian 的系統上，執行以下命令就可以安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install meld</span></span></code></pre></div><h3 id="高效地工作" tabindex="-1">高效地工作 <a class="header-anchor" href="#高效地工作" aria-label="Permalink to “高效地工作”">​</a></h3><p>以上提到的五個工具除了幫助你完成工作，而且有助於提高效率。儘管適用於 Linux 開發者的工具有很多，但對於以上幾個類別，你最好分別使用一個對應的工具。</p><hr>',8)),l("p",null,[t[25]||(t[25]=i("via: ",-1)),s(e,{href:"https://www.linux.com/learn/intro-to-linux/2018/8/5-essential-tools-linux-development"},{default:n(()=>[...t[24]||(t[24]=[i("https://www.linux.com/learn/intro-to-linux/2018/8/5-essential-tools-linux-development",-1)])]),_:1})]),l("p",null,[t[30]||(t[30]=i("作者：",-1)),s(e,{href:"https://www.linux.com/users/jlwallen"},{default:n(()=>[...t[26]||(t[26]=[i("Jack Wallen",-1)])]),_:1}),t[31]||(t[31]=i(" 選題：",-1)),s(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[27]||(t[27]=[i("lujun9972",-1)])]),_:1}),t[32]||(t[32]=i(" 譯者：",-1)),s(e,{href:"https://github.com/HankChow"},{default:n(()=>[...t[28]||(t[28]=[i("HankChow",-1)])]),_:1}),t[33]||(t[33]=i(" 校對：",-1)),s(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[29]||(t[29]=[i("wxy",-1)])]),_:1})]),l("p",null,[t[36]||(t[36]=i("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[34]||(t[34]=[i("LCTT",-1)])]),_:1}),t[37]||(t[37]=i(" 原創編譯，",-1)),s(e,{href:"https://linux.cn/"},{default:n(()=>[...t[35]||(t[35]=[i("Linux中國",-1)])]),_:1}),t[38]||(t[38]=i(" 榮譽推出",-1))])])}const L=p(d,[["render",m]]);export{w as __pageData,L as default};
